import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";

/**
 * Where the worker puts generated bytes. A worker has no browser session, so how it may write to the
 * private bucket is an explicit, security-relevant choice:
 *
 *   LocalDiskSink              memory/demo mode and tests: `.local-storage/<objectPath>`, served by the same
 *                              authorised route as every other asset.
 *   SupabaseServiceKeySink     PRODUCTION worker: a server-only secret key that exists ONLY in the worker's
 *                              environment: PRISM_STUDIO_WORKER_SUPABASE_SECRET_KEY (preferred), or the legacy
 *                              PRISM_STUDIO_WORKER_SERVICE_KEY. Never in the Next.js app, never in the browser,
 *                              never in a snapshot. Fails closed when absent or when it is not a secret key.
 *   SupabaseUserSessionSink    DEV/TEST ONLY, opt-in (PRISM_STUDIO_WORKER_DEV_STORAGE=1): the worker signs in
 *                              as the project owner with the test credentials so Storage RLS itself authorises
 *                              the upload. Refused in production.
 *
 * Object keys are always <project_id>/<asset_id>/<filename>, built by buildObjectPath, so Storage RLS and
 * project-scoped cleanup keep working.
 */
export interface OutputSink {
  readonly name: "local" | "supabase";
  readonly bucket: string | null;
  put(objectPath: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(objectPath: string): Promise<Uint8Array | null>;
  remove(objectPath: string): Promise<void>;
  /**
   * A SHORT-LIVED URL a provider can fetch an input from. Execution transport only: never logged, stored,
   * or placed in a package. `null` when this sink cannot sign (local disk).
   */
  signedUrl?(objectPath: string, ttlSeconds: number): Promise<string | null>;
}

export const LOCAL_ROOT = path.join(process.cwd(), ".local-storage");

export class LocalDiskSink implements OutputSink {
  readonly name = "local" as const;
  readonly bucket = null;
  constructor(private readonly root: string = LOCAL_ROOT) {}

  private resolve(objectPath: string): string {
    const full = path.resolve(this.root, objectPath);
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Invalid storage path");
    return full;
  }
  async put(objectPath: string, bytes: Uint8Array): Promise<void> {
    const full = this.resolve(objectPath);
    await mkdir(path.dirname(full), { recursive: true });
    await writeFile(full, bytes);
  }
  async get(objectPath: string): Promise<Uint8Array | null> {
    try {
      return await readFile(this.resolve(objectPath));
    } catch {
      return null;
    }
  }
  async remove(objectPath: string): Promise<void> {
    await rm(this.resolve(objectPath), { force: true });
  }
}

class SupabaseSink implements OutputSink {
  readonly name = "supabase" as const;
  constructor(
    private readonly client: SupabaseClient,
    readonly bucket: string,
  ) {}
  private get files() {
    return this.client.storage.from(this.bucket);
  }
  async put(objectPath: string, bytes: Uint8Array, contentType: string): Promise<void> {
    const { error } = await this.files.upload(objectPath, bytes, { contentType, upsert: false });
    if (error) throw new Error(`Storage upload failed: ${error.message}`);
  }
  async get(objectPath: string): Promise<Uint8Array | null> {
    const { data, error } = await this.files.download(objectPath);
    if (error || !data) return null;
    return new Uint8Array(await data.arrayBuffer());
  }
  async remove(objectPath: string): Promise<void> {
    const { error } = await this.files.remove([objectPath]);
    if (error) throw new Error(`Storage delete failed: ${error.message}`);
  }
  async signedUrl(objectPath: string, ttlSeconds: number): Promise<string | null> {
    const ttl = Math.max(30, Math.min(ttlSeconds, 900));
    const { data, error } = await this.files.createSignedUrl(objectPath, ttl);
    if (error || !data?.signedUrl) return null;
    return data.signedUrl;
  }
}

type Env = Record<string, string | undefined>;

export class SinkConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SinkConfigError";
  }
}

/**
 * Chooses the sink for this worker. Throws SinkConfigError (with an actionable, secret-free message) when
 * Supabase mode has no way to write storage. Generation itself can still be tested end-to-end with the
 * local sink.
 */
export async function createOutputSink(
  env: Env,
  mode: "memory" | "supabase",
  bucket = "prism-assets",
): Promise<OutputSink> {
  if (mode === "memory") return new LocalDiskSink();
  const url = env.NEXT_PUBLIC_SUPABASE_URL;
  const publishable = env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
  if (!url || !url.includes("lyqdxiyjperhniwhzsvg")) {
    throw new SinkConfigError("NEXT_PUBLIC_SUPABASE_URL must target the Prism Studio project.");
  }
  const secret =
    env.PRISM_STUDIO_WORKER_SUPABASE_SECRET_KEY?.trim() || env.PRISM_STUDIO_WORKER_SERVICE_KEY?.trim();
  if (secret) return secretKeySink({ url, publishable, secret, bucket, what: "worker" });
  const email = env.PRISM_STUDIO_DEV_USER_EMAIL;
  const password = env.PRISM_STUDIO_DEV_USER_PASSWORD;
  if (
    env.NODE_ENV !== "production" &&
    env.PRISM_STUDIO_WORKER_DEV_STORAGE === "1" &&
    publishable &&
    email &&
    password
  ) {
    const client = createClient(url, publishable, { auth: { persistSession: false } });
    const { error } = await client.auth.signInWithPassword({ email, password });
    if (error) throw new SinkConfigError("Worker could not sign in with the dev user credentials.");
    return new SupabaseSink(client, bucket);
  }
  throw new SinkConfigError(
    "The worker has no way to write Supabase Storage. Set PRISM_STUDIO_WORKER_SUPABASE_SECRET_KEY " +
      "(or the legacy PRISM_STUDIO_WORKER_SERVICE_KEY) on the worker host. For local development only: " +
      "PRISM_STUDIO_WORKER_DEV_STORAGE=1 with PRISM_STUDIO_DEV_USER_EMAIL/PASSWORD.",
  );
}

/**
 * A Storage sink authorised by a server SECRET key, validated the same way for every holder: the URL must target the
 * Prism Studio project and the key must be a secret key (never the publishable/anon key). Callers pass the key they
 * own (the worker's, or the Prism server's dedicated agent-relay key); this function reads no environment itself.
 */
export function secretKeySink(o: {
  url: string | undefined;
  publishable: string | undefined;
  secret: string;
  bucket?: string;
  what: string;
}): OutputSink {
  if (!o.url || !o.url.includes("lyqdxiyjperhniwhzsvg"))
    throw new SinkConfigError("NEXT_PUBLIC_SUPABASE_URL must target the Prism Studio project.");
  if (!isServerSecretKey(o.secret) || (o.publishable && o.secret === o.publishable))
    throw new SinkConfigError(
      `The ${o.what} Storage credential is not a server secret key (a publishable/anon key was supplied).`,
    );
  return new SupabaseSink(
    createClient(o.url, o.secret, { auth: { persistSession: false } }),
    o.bucket ?? "prism-assets",
  );
}

/** `sb_secret_...` keys, or the legacy service_role JWT. A publishable/anon key must never be accepted. */
export function isServerSecretKey(key: string): boolean {
  if (key.startsWith("sb_secret_")) return true;
  if (key.startsWith("sb_publishable_")) return false;
  const parts = key.split(".");
  if (parts.length !== 3) return false;
  try {
    const payload = JSON.parse(Buffer.from(parts[1]!, "base64url").toString("utf8")) as { role?: string };
    return payload.role === "service_role";
  } catch {
    return false;
  }
}
